return items.map(item => {
  const job = item.json;

  const location = job.location || '';
  const pay = job.salary || job.compensation || 'N/A';

  const jobTitle = $('Job Search Webhook').first().json.body.jobTitle || '';

  // Generic role words ("developer", "engineer", ...) match almost every posting —
  // require the more specific technical/skill words (e.g. "php", "laravel") instead,
  // falling back to all words only if nothing specific remains.
  const GENERIC_WORDS = new Set(['developer', 'engineer', 'programmer', 'specialist', 'senior', 'junior', 'lead', 'software', 'full', 'stack', 'fullstack', 'api', 'backend', 'back-end', 'web']);
  const allTitleWords = jobTitle.split(/\s+/).filter(Boolean);
  const specificWords = allTitleWords.filter(w => !GENERIC_WORDS.has(w.toLowerCase()));
  const titleWords = (specificWords.length ? specificWords : allTitleWords).map(w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  const relevantTitles = titleWords.length
    ? [new RegExp(titleWords.join('|'), 'i')]
    : [/./];

  const isMatch = relevantTitles.some(regex => regex.test(job.title || job.position || ''));

  const postDate = new Date(job.date);
  const hoursSincePost = (Date.now() - postDate) / 1000 / 60 / 60;
  const isRecent = hoursSincePost <= 24;

  if (!isMatch || !isRecent) return null;

  return {
    json: {
      title: job.title || job.position || '',
      company: job.company,
      description: job.description,
      link: job.url,
      location: location,
      date: job.date,
      pay: pay,
    }
  };
}).filter(item => item !== null);

return items.map(item => {
  const rawOutput = item.json.output;
  let parsedJson;

  try {
    // Step 1: Clean AI output by stripping ```json ... ```
    const cleaned = rawOutput
      .replace(/^```json\s*/i, '') // Remove leading ```json
      .replace(/```$/, '')         // Remove trailing ```

    // Step 2: Attempt to parse cleaned string
    parsedJson = JSON.parse(cleaned);
  } catch (error) {
    // If parsing fails, fallback to logging format
    console.error("Failed to parse AI JSON output. Error:", error.message);
    console.error("Problematic Raw Output:", rawOutput);

    parsedJson = {
      error: "Invalid JSON from AI",
      raw_ai_output: rawOutput,
      title: item.json.title || "N/A",
      company: item.json.company || "N/A",
      link: item.json.link || "N/A"
    };
  }

  // Format current date as MM/DD/YYYY
  const now = new Date();
  const mmddyyyy = `${(now.getMonth() + 1).toString().padStart(2,    '0')}/${now.getDate().toString().padStart(2, '0')}/${now.getFullYear()}`;

  // Attach savedAt date
  parsedJson.savedAt = mmddyyyy;

  return { json: parsedJson };
});

