const jobTitle = $('Job Search Webhook').first().json.body.jobTitle;
const rawLocation = $('Job Search Webhook').first().json.body.location || '';
const wantsRemote = /\bremote\b/i.test(rawLocation);

// Adzuna's geocoder can't resolve compound strings like "Remote, Hybrid, City" —
// strip those qualifiers and keep the actual place name (same cleanup used for
// Resolve Google Jobs Location; freeform input tends to put the city last).
const cleanedParts = rawLocation
  .replace(/\b(remote|hybrid)\b/gi, '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);
// Search every real city mentioned, not just one guessed segment — the Adzuna
// Loop downstream already iterates one {what, where} pair at a time, so let it
// process all of them instead of silently dropping cities.
const locations = cleanedParts.length ? cleanedParts : [rawLocation];

// Adzuna requires a country code in the URL path (not just free-text location).
// Detect India vs default to US based on keywords in the user's raw location string.
const INDIA_KEYWORDS = ['india', 'ahmedabad', 'gandhinagar', 'mumbai', 'delhi', 'bangalore', 'bengaluru', 'pune', 'hyderabad', 'chennai', 'kolkata', 'surat', 'jaipur', 'noida', 'gurgaon', 'gurugram'];
const locationLower = rawLocation.toLowerCase();
const country = INDIA_KEYWORDS.some(kw => locationLower.includes(kw)) ? 'in' : 'us';

const queries = locations.map(where => ({ what: jobTitle, where, country }));

// Adzuna has no "remote" location filter (where=Remote always returns 0) — the
// only way it surfaces remote-tagged listings is a keyword in `what`, searched
// country-wide (where left blank). Add that as its own query when requested.
if (wantsRemote) {
  queries.push({ what: `${jobTitle} remote`, where: '', country });
}

return [{
  json: {
    json: queries
  }
}];

// Enhanced Deduplicate v3.6 - More aggressive fuzzy matching
const seen = new Set();
const seenNormalized = new Set();

function normalize(str) {
  if (!str) return '';
  return str.toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')      // Remove all punctuation
    .replace(/\b(inc|llc|ltd|corp|corporation|company|co|group|holdings|services|solutions|technologies|tech|remote|hybrid|onsite)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeTitle(str) {
  if (!str) return '';
  return str.toLowerCase()
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\b(senior|sr|junior|jr|lead|principal|staff|i{1,3}|iv|v|remote|hybrid|contract|temp|temporary)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Simple similarity check: % of shared words
function wordSimilarity(a, b) {
  if (!a || !b) return 0;
  const wordsA = new Set(a.split(' ').filter(w => w.length > 2));
  const wordsB = new Set(b.split(' ').filter(w => w.length > 2));
  if (wordsA.size === 0 || wordsB.size === 0) return 0;
  let shared = 0;
  for (const w of wordsA) { if (wordsB.has(w)) shared++; }
  return shared / Math.min(wordsA.size, wordsB.size);
}

const deduped = items.filter(item => {
  const job = item.json;

  // Exact key: title|company|location
  const exactKey = `${(job.title||'').toLowerCase()}|${(job.company||'').toLowerCase()}|${(job.location||'').toLowerCase()}`;
  if (seen.has(exactKey)) return false;
  seen.add(exactKey);

  // Normalized key: stripped title | stripped company (catches "Sr." vs "Senior", "Inc." vs "")
  const normTitle = normalizeTitle(job.title);
  const normCompany = normalize(job.company);
  const normKey = `${normTitle}|${normCompany}`;
  if (seenNormalized.has(normKey)) return false;

  // Fuzzy check: compare against all seen normalized titles for same company
  for (const seenKey of seenNormalized) {
    const [seenTitle, seenComp] = seenKey.split('|');
    if (seenComp === normCompany && wordSimilarity(normTitle, seenTitle) >= 0.8) {
      return false; // 80%+ word overlap with same company = duplicate
    }
  }

  seenNormalized.add(normKey);

  // Clean up: remove `url` field, keep `link`
  const { url, ...cleanedJob } = job;
  item.json = cleanedJob;
  return true;
});

return deduped;

return items.filter(item => {
  const title = item.json.title?.toLowerCase() || '';
  // ── CONFIGURE: Add job title keywords to exclude ──────────────────────────
  if (title.includes('sales')) return false;
  if (title.includes('marketing')) return false;
  // Add more exclusions as needed, e.g.:
  // if (title.includes('data scientist')) return false;
