  // ─────────────────────────────────────────────────────────────────────────
  return true;
});

return items.map(item => {
  const job = item.json;
  const location = job.location?.area?.join(', ') || job.location?.display_name || '';
  const company = job.company?.display_name || '';

  // Combine salary range
  const salaryMin = job.salary_min;
  const salaryMax = job.salary_max;
  let pay = "N/A";
  if (salaryMin && salaryMax) {
    pay = `$${salaryMin.toLocaleString()} - $${salaryMax.toLocaleString()}`;
  }

  return {
    json: {
      title: job.title,
      company: company,
      description: job.description,
      link: job.redirect_url || job.url || null, // ✅ normalize field name to "link"
      location: location,
      date: job.created,
      pay,
      salary_min: salaryMin,
      salary_max: salaryMax,
      salary_is_predicted: job.salary_is_predicted === "1"
    }
  };
});

// Normalize Salary v3.6 - NOW DROPS HOURLY JOBS
return items.filter(item => {
  const job = item.json;
  const pay = (job.pay || '').toLowerCase();

  // KILL hourly pay patterns: "$28.85/hr", "$33 an hour", "hourly", etc.
  if (/(?:hour|hourly|\/hr|per hr)/i.test(pay)) return false;

  // KILL small dollar amounts with decimals (e.g. "$28.85 - $33.65")
  // These are almost always hourly rates
  const amounts = [...pay.matchAll(/\$(\d+(?:\.\d{2})?)/g)].map(m => parseFloat(m[1]));
  if (amounts.length > 0 && amounts.every(a => a < 200)) return false;

  return true;
}).map(item => {
  const job = item.json;

  let pay = job.pay || null;
  if (!pay && job.salary_min && job.salary_max) {
    const min = Math.round(job.salary_min).toLocaleString();
    const max = Math.round(job.salary_max).toLocaleString();
    pay = `$${min} - $${max}`;
  } else if (!pay && job.salary_min) {
    const min = Math.round(job.salary_min).toLocaleString();
    pay = `$${min}+`;
  }

  const { salary_min, salary_max, salary_is_predicted, ...rest } = job;
  return { json: { ...rest, pay: pay || 'N/A' } };
});

// ── SCORING CONFIGURATION — tune these to your target role ────────────────
// Add keywords relevant to your field and assign point values.
// Higher points = stronger signal that the job matches your search.

const CORE_FUNCTION_KEYWORDS = {
  // ── Replace with YOUR domain keywords ────────────────────────────────────
  // Examples below are for a generic "automation / AI" job search.
  // Change or add entries that match YOUR target role.
  'automation': 40,
  'process improvement': 30,
  'optimization': 30,
  'digital transformation': 35,
  'artificial intelligence': 30,
  'ai': 25,
  'analytics': 25,
  'operations': 20,
};

const HIGH_VALUE_SKILL_KEYWORDS = {
  // Technical skills that boost a job's relevance score
  'python': 20,
  'sql': 20,
  'power bi': 20,
  'tableau': 20,
  'llm': 50,
  'ai agent': 50,
  'generative ai': 50,
  'roi': 20,
};

const TITLE_BONUS_KEYWORDS = [
  // If ANY of these appear in the job title, add a flat bonus
  'automation manager',
  'automation specialist',
  'process automation',
  'digital transformation',
  'intelligent automation',
  'operations manager',
];

const NEGATIVE_TITLE_KEYWORDS = [
  // Jobs whose titles contain these words are auto-rejected
  'sales', 'marketing', 'underwriter',
  'credit risk', 'banker', 'loan', 'financial advisor',
  'driver', 'warehouse associate', 'forklift', 'intern',
];

const SENIORITY_MODIFIERS = {
  'junior': -100,
  'entry-level': -100,
  'intern': -100,
  'senior': 30,
  'lead': 30,
  'principal': 40,
  'manager': 30,
  'director': 50,
  'vp': 45,
  'vice president': 45,
};
// ─────────────────────────────────────────────────────────────────────────────

function calculateScore(job) {
  const title = (job.title || '').toLowerCase();
  const description = (job.description || '').toLowerCase();
  const fullText = `${title} ${description}`;

  let score = 0;
  let matchedKeywords = [];

  // 1. Negative title kill switch
  for (const keyword of NEGATIVE_TITLE_KEYWORDS) {
    if (title.includes(keyword)) {
      return { score: -999, matchedKeywords: [`Negative title: ${keyword}`] };
    }
  }

  // 2. Hourly pay kill switch
  const payStr = (job.pay || '').toLowerCase();
  if (/(?:hour|hourly|\/hr|per hr)/i.test(payStr)) {
    return { score: -999, matchedKeywords: ['Hourly pay — auto-reject'] };
  }
  const payAmounts = [...payStr.matchAll(/\$(\d+(?:\.\d{2})?)/g)].map(m => parseFloat(m[1]));
  if (payAmounts.length > 0 && payAmounts.every(a => a < 200)) {
    return { score: -999, matchedKeywords: ['Hourly pay (small $) — auto-reject'] };
  }

  // 3. Core function keywords
  for (const [keyword, points] of Object.entries(CORE_FUNCTION_KEYWORDS)) {
    if (fullText.includes(keyword)) {
      score += points;
      matchedKeywords.push(`${keyword} (+${points})`);
    }
  }

  // 4. High-value skill keywords
  for (const [keyword, points] of Object.entries(HIGH_VALUE_SKILL_KEYWORDS)) {
    if (fullText.includes(keyword)) {
      score += points;
      matchedKeywords.push(`${keyword} (+${points})`);
    }
  }

  // 5. Title bonus
  let titleBonus = false;
  for (const kw of TITLE_BONUS_KEYWORDS) {
    if (title.includes(kw)) {
      score += 60;
      matchedKeywords.push(`Title match: ${kw} (+60)`);
      titleBonus = true;
      break;
    }
  }

  // 6. Seniority modifiers
  for (const [keyword, mod] of Object.entries(SENIORITY_MODIFIERS)) {
    if (title.includes(keyword)) {
      score += mod;
      if (mod > 0) matchedKeywords.push(`Seniority: ${keyword} (+${mod})`);
    }
  }

  // 7. Auto-reject if no signal at all
  const hits = Object.keys(CORE_FUNCTION_KEYWORDS).filter(k => fullText.includes(k));
  const techHits = Object.keys(HIGH_VALUE_SKILL_KEYWORDS).filter(k => fullText.includes(k));
  if (hits.length === 0 && techHits.length === 0 && !titleBonus) {
    return { score: -999, matchedKeywords: ['No relevant signal found'] };
  }

  // 8. Remote/Hybrid preference bonus — remote ranked above hybrid
  const locationText = (job.location || '').toLowerCase();
  const remoteText = `${fullText} ${locationText}`;
  const remoteSignal = /\b(remote|anywhere|work from home|wfh)\b/.test(remoteText);
  const hybridSignal = /\bhybrid\b/.test(remoteText);
  if (remoteSignal) {
    score += 25;
    matchedKeywords.push('Remote (+25)');
  } else if (hybridSignal) {
    score += 10;
    matchedKeywords.push('Hybrid (+10)');
  }

  return { score, matchedKeywords };
}

function normalizeForJobKey(str) {
  if (!str) return '';
  return str.toLowerCase()
    .replace(/[^\w\s]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/\b(inc|llc|ltd|corp|corporation|company|co|group|holdings|services|solutions|technologies|tech)\b/gi, '')
    .trim();
}
function normalizeTitleForJobKey(str) {
  if (!str) return '';
  return str.toLowerCase()
    .replace(/[^\w\s]/g, '')
    .replace(/\b(senior|sr|junior|jr|lead|principal|staff|remote|hybrid|contract)\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim();
}

return items.map(item => {
  const job = item.json;
  const { score, matchedKeywords } = calculateScore(job);
  const jobKey = `${normalizeTitleForJobKey(job.title)}|${normalizeForJobKey(job.company)}`;
  return {
    json: {
      ...job,
      score,
      reason: matchedKeywords.join(', '),
      jobKey,
    }
  };
});

const joobleJobs = items[0].json.jobs || [];

const jobTitle = $('Job Search Webhook').first().json.body.jobTitle || '';

// Jooble's own search returns broadly related postings, not strict keyword
// matches (same behavior confirmed on LinkedIn/RemoteOK) — require the
// specific tech terms from the search title, and rank matches by the order
// those terms appear in the search (e.g. "laravel php developer" means
// laravel-matching jobs rank above php-only matches).
const GENERIC_WORDS = new Set(['developer', 'engineer', 'programmer', 'specialist', 'senior', 'junior', 'lead', 'software', 'full', 'stack', 'fullstack', 'api', 'backend', 'back-end', 'web']);
const allTitleWords = jobTitle.split(/\s+/).filter(Boolean);
const specificWords = allTitleWords.filter(w => !GENERIC_WORDS.has(w.toLowerCase()));
const priorityWords = (specificWords.length ? specificWords : allTitleWords).map(w => w.toLowerCase());

function matchPriority(title) {
  const t = (title || '').toLowerCase();
  const idx = priorityWords.findIndex(w => t.includes(w));
  return idx === -1 ? Infinity : idx;
}

return joobleJobs
  .filter(job => matchPriority(job.title) !== Infinity)
  .sort((a, b) => matchPriority(a.title) - matchPriority(b.title))
  .map(job => {
    const snippet = job.snippet;
    let cleanDescription = '';

    if (snippet) {
      cleanDescription = snippet
        .replace(/<[^>]*>?/gm, ' ')
        .replace(/&[a-zA-Z0-9#]+;/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    return {
      json: {
        title: job.title,
        company: job.company,
        location: job.location,
        description: cleanDescription,
        link: job.link,
        pay: job.salary || 'N/A',
        date: job.updated,
      }
    };
  });

