async function resolveLocation(query) {
  if (!query) return null;
  try {
    const results = await $helpers.httpRequest({
      method: 'GET',
      url: 'https://serpapi.com/locations.json',
      qs: { q: query, limit: 1 },
      json: true,
    });
    return Array.isArray(results) && results.length > 0 ? results[0].canonical_name : null;
  } catch (e) {
    return null;
  }
}

// Try the full cleaned text first (handles real "City, State" input),
// then fall back to individual comma-separated segments, last-first
// (freeform Indian-style input tends to put the city last, e.g. "MG Road, Ahmedabad").
let canonical = await resolveLocation(cleanedParts.join(', '));

if (!canonical) {
  for (const part of [...cleanedParts].reverse()) {
    canonical = await resolveLocation(part);
    if (canonical) break;
  }
}

return items.map(item => ({
  json: {
    ...item.json,
    googleJobsLocation: canonical || '',
  },
}));

